const keys={};addEventListener('keydown',e=>{const k=e.key.toLowerCase();keys[k]=true;if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();if(k===' '&&!e.repeat)castSpell()});addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
