function burst(position,color=0x9fffe0,count=10){for(let i=0;i<count;i++){const p=new THREE.Mesh(new THREE.SphereGeometry(.045+Math.random()*.04,6,6),new THREE.MeshBasicMaterial({color,transparent:true}));p.position.copy(position);scene.add(p);particles.push({mesh:p,vel:new THREE.Vector3((Math.random()-.5)*3,Math.random()*3,(Math.random()-.5)*3),life:.65+Math.random()*.45})}}
function castSpell(){if(!gameStarted||gameOver||attackCooldown>0)return;attackCooldown=.42;staffGem.material=crystalMat;const target=enemies.filter(e=>e.hp>0).sort((a,b)=>a.group.position.distanceTo(player.position)-b.group.position.distanceTo(player.position))[0];if(!target){showToast('No hay criaturas cerca. ¡Sigue el sendero!');return}const origin=player.position.clone().add(new THREE.Vector3(.2,1.15,0));const orb=new THREE.Mesh(new THREE.SphereGeometry(.17,10,10),new THREE.MeshStandardMaterial({color:0xb8fff0,emissive:0x50e7c8,emissiveIntensity:2,roughness:.2}));orb.position.copy(origin);scene.add(orb);const glow=new THREE.PointLight(0x7affdd,1.5,2);orb.add(glow);projectiles.push({mesh:orb,target,life:2,speed:14});burst(origin,0x9fffe0,4)}
function damageEnemy(e,amount=1){if(e.hp<=0)return;e.hp-=amount;e.hit=.22;e.bar.visible=true;e.bar.userData.fill.scale.x=Math.max(.001,e.hp/e.maxHp);e.bar.userData.fill.position.x=-(1-e.hp/e.maxHp)*.72;burst(e.group.position.clone().add(new THREE.Vector3(0,1,0)),e.type==='boss'?0xd579ed:0xa7ffd4,5);if(e.type==='boss'){document.getElementById('bosshp').style.width=`${Math.max(0,e.hp/e.maxHp*100)}%`}
 if(e.hp<=0){e.group.visible=false;kills++;crystals+=e.type==='boss'?8:e.type==='goblin'?2:1;document.getElementById('crystals').innerHTML=`${crystals} <span style="font-size:11px">✧</span>`;burst(e.group.position.clone().add(new THREE.Vector3(0,1,0)),e.type==='boss'?0xd579ed:0x9fffd8,18);showToast(e.type==='boss'?'¡El demonio ha sido vencido! +8 cristales':'+'+(e.type==='goblin'?2:1)+' cristal'+(e.type==='goblin'?'es':''));if(e.type==='boss'){setTimeout(()=>finishGame(true),1100)}else if(enemies.filter(q=>q.hp>0).length===0){stage++;if(stage<4)setTimeout(spawnWave,1200);else finishGame(true)}}}
function hurtPlayer(amount){if(invuln>0||gameOver)return;health=Math.max(0,health-amount);invuln=.8;setHealth();burst(player.position.clone().add(new THREE.Vector3(0,1,0)),0xff888d,8);if(health<=0)finishGame(false);else showToast('¡Cuidado! Has perdido vitalidad.')}
function finishGame(win){gameOver=true;const c=document.getElementById('endcard');c.style.display='block';c.innerHTML=win?`<div class="eyebrow">✦ el bosque vuelve a brillar ✦</div><h1>¡Victoria!<span>La sombra se ha ido</span></h1><p class="intro">Celisbeth ha salvado el Bosque Eterno. Has reunido ${crystals} cristales mágicos y derrotado a todas las criaturas.</p><button class="btn" id="again">Jugar de nuevo&nbsp; ↻</button>`:`<div class="eyebrow">✦ la aventura no termina aquí ✦</div><h1>¡No te rindas!<span>El bosque te necesita</span></h1><p class="intro">Las sombras han ganado esta batalla, pero Celisbeth aún puede volver a intentarlo.</p><button class="btn" id="again">Intentar de nuevo&nbsp; ↻</button>`;document.getElementById('startcard').style.display='none';document.getElementById('overlay').classList.remove('hidden');document.getElementById('again').onclick=resetGame}
function resetGame(){enemies.forEach(e=>scene.remove(e.group));enemies.length=0;projectiles.forEach(p=>scene.remove(p.mesh));projectiles.length=0;health=100;crystals=0;kills=0;stage=0;gameOver=false;gameStarted=true;player.position.set(0,0,6);document.getElementById('crystals').innerHTML='0 <span style="font-size:11px">✧</span>';document.getElementById('bossbar').classList.remove('visible');document.getElementById('bosshp').style.width='100%';document.getElementById('startcard').style.display='block';document.getElementById('endcard').style.display='none';document.getElementById('overlay').classList.add('hidden');setHealth();spawnWave()}
document.getElementById('start').onclick=()=>{gameStarted=true;player.position.set(0,0,6);document.getElementById('overlay').classList.add('hidden');spawnWave()};
let audioOn=false,audioCtx;document.getElementById('sound').onclick=()=>{audioOn=!audioOn;document.getElementById('sound').textContent=audioOn?'♫':'♪';if(audioOn&&!audioCtx){audioCtx=new (window.AudioContext||window.webkitAudioContext)();const osc=audioCtx.createOscillator(),gain=audioCtx.createGain();osc.type='sine';osc.frequency.value=110;gain.gain.value=.018;osc.connect(gain);gain.connect(audioCtx.destination);osc.start()}};

